import{_ as t,o,c as d,a3 as a}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"Bazel API","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Bazel API | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/bazel-api"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/bazel-api"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/bazel-api"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/bazel-api"}]]},"headers":[],"relativePath":"xclang/reference/bazel-api.md","filePath":"en/xclang/reference/bazel-api.md","lastUpdated":1791579933000}'),c={name:"xclang/reference/bazel-api.md"};function r(s,e,n,l,i,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="bazel-api" tabindex="-1">Bazel API <a class="header-anchor" href="#bazel-api" aria-label="Permalink to &quot;Bazel API&quot;">​</a></h1><p>Everything the <code>xclang</code> Bazel module offers. How to use it is in <a href="./../integrations/bazel">Bazel</a>; this page is the list. The module needs Bazel 9 and rules_cc 0.2.25. It is <code>packages/bazel</code> of the repository, and is published to <a href="https://bazel.clice.io" target="_blank" rel="noreferrer">bazel.clice.io</a> for every release.</p><h2 id="toolchains" tabindex="-1">Toolchains <a class="header-anchor" href="#toolchains" aria-label="Permalink to &quot;Toolchains&quot;">​</a></h2><p>The module registers, for every host, one C++ toolchain per target: <code>@xclang//bazel/toolchains:&lt;host&gt;</code> for the host itself, and <code>&lt;host&gt;-to-&lt;target&gt;</code> for the others, <code>@xclang//bazel/toolchains/musl:&lt;host&gt;-to-&lt;target&gt;</code> for the musl targets and <code>@xclang//bazel/toolchains/msvc:&lt;host&gt;-to-&lt;target&gt;</code> for the MSVC ones, registered first. Each is the host archive configured for the target, and only the archive of the machine Bazel runs on is downloaded. The MSVC targets, and the macOS targets off macOS hosts, build against the vendor SDK the root module fetches (<a href="#tags">tags</a>); without it, their toolchain fails the build and says why.</p><p>Every toolchain:</p><ul><li>builds Windows programs named <code>.exe</code>, and shared libraries named <code>.dll</code>;</li><li>links libraries statically into tests and programs (<a href="./../design/bazel-module#static-by-default">static by default</a>);</li><li>compiles the headers of other repositories as system headers (<code>-isystem</code>);</li><li>redacts <code>__DATE__</code>, <code>__TIME__</code> and <code>__TIMESTAMP__</code>;</li><li>puts no absolute path on a command line (<a href="./../design/bazel-module#no-absolute-paths">no absolute paths</a>).</li></ul><h2 id="platforms" tabindex="-1">Platforms <a class="header-anchor" href="#platforms" aria-label="Permalink to &quot;Platforms&quot;">​</a></h2><p><code>@xclang//platforms:&lt;target&gt;</code>, for <code>--platforms</code>:</p><table tabindex="0"><thead><tr><th>platform</th><th>also</th><th>target</th></tr></thead><tbody><tr><td><code>x86_64-unknown-linux-gnu</code></td><td><code>x86_64-linux-gnu</code></td><td>Linux x64, glibc 2.17</td></tr><tr><td><code>aarch64-unknown-linux-gnu</code></td><td><code>aarch64-linux-gnu</code></td><td>Linux arm64, glibc 2.17</td></tr><tr><td><code>x86_64-w64-mingw32</code></td><td><code>x86_64-w64-windows-gnu</code></td><td>Windows x64, MinGW-w64 (UCRT)</td></tr><tr><td><code>aarch64-w64-mingw32</code></td><td><code>aarch64-w64-windows-gnu</code></td><td>Windows arm64, MinGW-w64 (UCRT)</td></tr><tr><td><code>aarch64-apple-darwin</code></td><td><code>arm64-apple-darwin</code></td><td>macOS arm64; off macOS hosts, with Apple&#39;s SDK</td></tr><tr><td><code>x86_64-apple-darwin</code></td><td></td><td>macOS x64; off macOS hosts, with Apple&#39;s SDK</td></tr><tr><td><code>x86_64-pc-windows-msvc</code></td><td></td><td>Windows x64, MSVC ABI, with Microsoft&#39;s SDK</td></tr><tr><td><code>aarch64-pc-windows-msvc</code></td><td></td><td>Windows arm64, MSVC ABI, with Microsoft&#39;s SDK</td></tr><tr><td><code>x86_64-unknown-linux-musl</code></td><td><code>x86_64-linux-musl</code></td><td>Linux x64, musl, static; from 23.1.2.10 on</td></tr><tr><td><code>aarch64-unknown-linux-musl</code></td><td><code>aarch64-linux-musl</code></td><td>Linux arm64, musl, static; from 23.1.2.10 on</td></tr></tbody></table><p>Each has <code>@platforms//os</code>, <code>@platforms//cpu</code> and a C library, <code>@xclang//platforms/libc:glibc</code>, <code>:musl</code>, <code>:mingw</code>, <code>:macosx</code> or <code>:msvc</code>. The toolchains ask a platform for os and cpu only, but those of musl and of the MSVC targets, which ask for <code>:musl</code> or <code>:msvc</code> too; so a platform of one&#39;s own with an os and a cpu works, and gets glibc on Linux and MinGW on Windows unless it names one of those.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><table tabindex="0"><thead><tr><th>feature</th><th>default</th><th></th></tr></thead><tbody><tr><td><code>asan</code>, <code>tsan</code>, <code>ubsan</code>, <code>lsan</code></td><td>off</td><td>sanitizers, for the whole build (<code>--features=asan</code>); <code>asan</code> compiles and links with the ASan libc++, or with the runtimes from source instrumented by it. None for the MinGW targets; for the MSVC targets <code>ubsan</code>, and <code>asan</code> for x64</td></tr><tr><td><code>msan</code></td><td>off</td><td>MemorySanitizer, for the whole build, with the runtimes from source (<code>--@xclang//runtimes:source</code>), which then include its runtime; Linux targets (glibc). In no release yet</td></tr><tr><td><code>cpp_modules</code></td><td>off</td><td>C++20 modules: <code>module_interfaces</code> of a <code>cc_library</code>/<code>cc_binary</code>, scanned by clang-scan-deps; needs <code>--experimental_cpp_modules</code></td></tr><tr><td><code>gc_sections</code></td><td>Linux targets: on in <code>opt</code>; Windows targets: off</td><td>lld&#39;s <code>--gc-sections</code>, lld-link&#39;s <code>/opt:ref</code> for the MSVC targets (<a href="./../design/windows#gc-sections-and-static-initializers">why not for Windows</a>)</td></tr><tr><td><code>thinlto_cache</code></td><td>on</td><td>the linker&#39;s ThinLTO cache, with flags only when <code>XCLANG_THINLTO_CACHE</code> names a directory</td></tr><tr><td><code>generate_dsym_file</code></td><td>off</td><td>macOS targets: the link makes <code>&lt;name&gt;.dSYM</code> (output group <code>dsyms</code>); <code>--apple_generate_dsym</code> turns it on for the build</td></tr><tr><td><code>supports_dynamic_linker</code></td><td>off</td><td>Bazel&#39;s dynamic linking of libraries into tests and programs; off, they link statically</td></tr><tr><td><code>release_strip</code></td><td>on</td><td>what <code>&lt;name&gt;.stripped</code> does: <code>--strip-unneeded</code> for ELF and COFF, <code>--strip-all</code> for Mach-O (<a href="./../features/debugging#strip">strip</a>)</td></tr><tr><td><code>modules_embed_all_files</code></td><td>on</td><td>a C++20 module interface&#39;s file embeds its sources (<code>-Xclang -fmodules-embed-all-files</code>): an importer that reads them (with <code>-g</code>) has them in the sandbox</td></tr><tr><td><code>no_exported_symbols</code></td><td>macOS targets: on in <code>opt</code></td><td>the program exports nothing (<code>-Wl,-no_exported_symbols</code>), so that its strip leaves no symbol to name a crash log&#39;s frames (<a href="./../features/debugging#strip">strip</a>); off for a program whose plugins bind to its symbols</td></tr><tr><td><code>generate_pdb_file</code></td><td>MSVC targets: on in <code>dbg</code></td><td>the link writes <code>&lt;name&gt;.pdb</code> (output group <code>pdb_file</code>), with paths relative to the execution root</td></tr><tr><td><code>dynamic_link_msvcrt</code></td><td>off</td><td>MSVC targets: the VC runtime&#39;s DLLs (<code>/MD</code>) in place of the hybrid CRT</td></tr><tr><td><code>debug_msvcrt</code></td><td>off</td><td>MSVC targets: the debug CRT (<code>/MTd</code>, <code>/MDd</code> with <code>dynamic_link_msvcrt</code>)</td></tr><tr><td><code>msvc_stl</code></td><td>off</td><td>MSVC targets: Microsoft&#39;s STL in place of libc++ (<code>-stdlib=platform</code>), for the whole build (<code>--features=msvc_stl</code>), which <code>@xclang//bazel:std</code> follows</td></tr></tbody></table><p>A feature is turned on for a build with <code>--features=&lt;name&gt;</code>, off with <code>--features=-&lt;name&gt;</code>, and for one target with <code>features = [&quot;&lt;name&gt;&quot;]</code> or <code>[&quot;-&lt;name&gt;&quot;]</code>.</p><h2 id="runtimes-from-source" tabindex="-1">Runtimes from Source <a class="header-anchor" href="#runtimes-from-source" aria-label="Permalink to &quot;Runtimes from Source&quot;">​</a></h2><p>In no release yet (<a href="./../design/roadmap#libc-on-demand">Unreleased</a>). Flags of the whole build, in <code>@xclang//runtimes</code> (<a href="./../features/runtimes-from-source">runtimes from source</a>):</p><table tabindex="0"><thead><tr><th>flag</th><th>default</th><th></th></tr></thead><tbody><tr><td><code>--@xclang//runtimes:source</code></td><td><code>false</code></td><td>libc++ (with libc++abi), libc++experimental and libunwind built from the toolchain&#39;s <code>libc++/src</code> for the target platform, with the build&#39;s features and <code>--copt</code>, and every compile and link against them in place of the prebuilt ones. Not for the MSVC targets</td></tr><tr><td><code>--@xclang//runtimes:hardening</code></td><td><code>none</code></td><td>libc++&#39;s hardening mode: <code>none</code>, <code>fast</code>, <code>extensive</code>, <code>debug</code></td></tr><tr><td><code>--@xclang//runtimes:abi_version</code></td><td><code>1</code></td><td>libc++&#39;s ABI version, <code>1</code> or <code>2</code></td></tr><tr><td><code>--@xclang//runtimes:abi_namespace</code></td><td><code>__&lt;version&gt;</code></td><td>libc++&#39;s inline namespace, <code>__&lt;name&gt;</code></td></tr><tr><td><code>--@xclang//runtimes:abi_defines</code></td><td>none</td><td>libc++&#39;s ABI macros, <code>_LIBCPP_ABI_*</code>, comma-separated</td></tr><tr><td><code>--@xclang//runtimes:exceptions</code></td><td><code>true</code></td><td><code>false</code>: libc++ and libc++abi without exceptions</td></tr><tr><td><code>--@xclang//runtimes:rtti</code></td><td><code>true</code></td><td><code>false</code>: libc++ without RTTI; needs <code>exceptions=false</code></td></tr></tbody></table><p>The runtimes are libraries of the host toolchain&#39;s repository, compiled as LLVM&#39;s CMake build compiles them (<code>bazel/runtimes_sources.bzl</code>) in a configuration of their own, the build&#39;s with <code>@xclang//runtimes:building</code> set, whose toolchain is the same without them. The build&#39;s sanitizer features instrument libc++ and libc++abi, not libunwind or MemorySanitizer&#39;s runtime. No runtime is compiled with ThinLTO.</p><h2 id="targets-and-rules" tabindex="-1">Targets and Rules <a class="header-anchor" href="#targets-and-rules" aria-label="Permalink to &quot;Targets and Rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>label</th><th></th></tr></thead><tbody><tr><td><code>@xclang//bazel:std</code></td><td>the <code>std</code> and <code>std.compat</code> modules of libc++, for the target platform, as a library to depend on; built with the <code>--cxxopt</code> of the build. For the MSVC targets with <code>msvc_stl</code> (or a release before 23.1.2.10), those of Microsoft&#39;s STL</td></tr><tr><td><code>xclang_debug_symbols(name, binary, gsymutil_args)</code> in <code>@xclang//bazel:debug_symbols.bzl</code></td><td><code>&lt;binary&gt;.gsym</code> for every target but the MSVC ones, by llvm-gsymutil with one thread (the same file each run; <code>gsymutil_args</code> come after <code>--num-threads=1</code>), and <code>&lt;binary&gt;.dSYM</code> for macOS ones (with <code>generate_dsym_file</code> on the <code>cc_binary</code>); llvm-gsymutil&#39;s output in the output group <code>gsym_log</code>. For an MSVC target, <code>&lt;binary&gt;.pdb</code> (with <code>generate_pdb_file</code>)</td></tr><tr><td><code>@xclang//bazel:llvm-gsymutil</code></td><td>the llvm-gsymutil of the machine&#39;s toolchain, for <code>bazel run</code>: <code>bazel run @xclang//bazel:llvm-gsymutil -- &lt;absolute .gsym&gt; --address=0x&lt;address&gt;</code></td></tr><tr><td><code>xclang_resource_dir(name, srcs)</code> in <code>@xclang//bazel:resource_dir.bzl</code></td><td>clang&#39;s resource directory laid out as <code>lib/clang/&lt;major&gt;/</code> in the rule&#39;s package, for a program <code>bin/&lt;name&gt;</code> of that package; <code>@libclang</code>&#39;s by default</td></tr></tbody></table><h2 id="tags" tabindex="-1">Tags <a class="header-anchor" href="#tags" aria-label="Permalink to &quot;Tags&quot;">​</a></h2><p>Of the module extension, <code>use_extension(&quot;@xclang//bazel:extensions.bzl&quot;, &quot;xclang&quot;)</code>, in the root module only: the vendor SDKs it fetches, from the vendor, accepting the vendor&#39;s license (<a href="./../integrations/bazel#vendor-sdks">build for MSVC, and for macOS anywhere</a>). The options are those of <code>xclang sdk fetch</code> (<a href="./../reference/xclang-command#versions">versions</a>).</p><table tabindex="0"><thead><tr><th>tag</th><th></th></tr></thead><tbody><tr><td><code>xclang.windows_sdk(accept_license, preset, msvc_version, sdk_version)</code></td><td>Microsoft&#39;s CRT, STL and Windows SDK, for the MSVC targets; <code>accept_license = True</code> accepts the Visual Studio Build Tools and Windows SDK licenses</td></tr><tr><td><code>xclang.macos_sdk(accept_license, preset, version)</code></td><td>Apple&#39;s macOS SDK, for the macOS targets off macOS hosts; <code>accept_license = True</code> accepts the Xcode and Apple SDKs Agreement</td></tr></tbody></table><h2 id="repositories" tabindex="-1">Repositories <a class="header-anchor" href="#repositories" aria-label="Permalink to &quot;Repositories&quot;">​</a></h2><p>From the module extension, <code>use_extension(&quot;@xclang//bazel:extensions.bzl&quot;, &quot;xclang&quot;)</code>; each is fetched only when a build uses it.</p><table tabindex="0"><thead><tr><th>repository</th><th></th></tr></thead><tbody><tr><td><code>@libclang</code></td><td>the target platform&#39;s libclang: <code>@libclang//:clangBasic</code>, <code>:LLVMSupport</code>, ... with their link interfaces; <code>:headers</code>; <code>:resource_dir</code>; <code>:AllTargetsInfos</code>, <code>:AllTargetsDescs</code>, <code>:AllTargetsAsmParsers</code>, <code>:AllTargetsDisassemblers</code>. With <code>--features=asan</code>, the ASan build. None for the MSVC targets: what depends on it is incompatible with them</td></tr><tr><td><code>@libclang_asan</code></td><td>the ASan build (Linux x64 and macOS arm64 targets)</td></tr><tr><td><code>@libclang_&lt;target&gt;</code></td><td>the libclang of one target</td></tr><tr><td><code>@llvm_option_inc</code></td><td>the option tables of clang, lld, llvm-lib and llvm-dlltool, as a header-only library</td></tr></tbody></table><h2 id="environment" tabindex="-1">Environment <a class="header-anchor" href="#environment" aria-label="Permalink to &quot;Environment&quot;">​</a></h2><p>Given with <code>--repo_env=&lt;name&gt;=&lt;value&gt;</code>:</p><table tabindex="0"><thead><tr><th>variable</th><th></th></tr></thead><tbody><tr><td><code>XCLANG_THINLTO_CACHE</code></td><td>an absolute directory for the ThinLTO cache of the linker; the module makes it (<a href="./../features/thinlto-cache#usage">the ThinLTO cache</a>)</td></tr><tr><td><code>XCLANG_ROOT</code></td><td>an unpacked host toolchain to use instead of the release&#39;s</td></tr><tr><td><code>XCLANG_LIBCLANG_ROOT</code>, <code>XCLANG_LIBCLANG_ASAN_ROOT</code></td><td>an unpacked host libclang, or its ASan build, to use instead of the release&#39;s</td></tr><tr><td><code>BAZEL_DO_NOT_DETECT_CPP_TOOLCHAIN=1</code></td><td>Bazel&#39;s own: turns rules_cc&#39;s detection of a local compiler off, recommended</td></tr></tbody></table><h2 id="the-release" tabindex="-1">The Release <a class="header-anchor" href="#the-release" aria-label="Permalink to &quot;The Release&quot;">​</a></h2><p><code>packages/bazel/bazel/versions.bzl</code> names the release the module downloads, and the sha256 of each of its archives, from the <code>SHA256SUMS</code> of the release. The version of the module is the release&#39;s.</p>',30)])])}const f=t(c,[["render",r]]);export{m as __pageData,f as default};
